  function defaultPageProductIds(key){let active=products.filter(p=>p.active!==false),tagged=(...words)=>active.filter(p=>words.some(w=>`${p.badge||''} ${p.category||''} ${p.name||''} ${p.collection||''}`.toLowerCase().includes(w)));if(key==='shopAll')return active.map(p=>p.id);if(key==='homeFeatured')return active.slice(0,4).map(p=>p.id);if(key==='newArrivals'){let found=tagged('new','arrival');return (found.length?found:active.slice(0,4)).map(p=>p.id);}if(key==='trending'){let found=tagged('trending','bestseller','best seller');return (found.length?found:active.slice(0,4)).map(p=>p.id);}if(key==='sale')return active.filter(p=>Number(p.old)>Number(p.price)).map(p=>p.id);if(key==='men'||key==='women')return active.filter(p=>(p.gender||'').toLowerCase()===key).map(p=>p.id);if(key==='premium'||key==='casual'||key==='gifts')return tagged(key,key==='gifts'?'gift':'__none__').map(p=>p.id);return [];}
