  function homeCategoryEditor(){let cats=homeCategories();const row=(c={},i=0)=>`<article class="home-category-editor"><header><b>Category ${i+1}</b><div><button type="button" class="carousel-remove-slide" data-category-up>&#8593;</button> <button type="button" class="carousel-remove-slide" data-category-down>&#8595;</button> <button type="button" class="carousel-remove-slide" data-category-remove>Remove</button></div></header><div class="home-category-fields"><label>Card title<input name="label" value="${esc(c.label||'')}" required placeholder="Shoes"></label><label>Link / destination<input name="href" value="${esc(c.href||'shop.html')}" required placeholder="shop.html?category=Shoes"></label><label class="home-category-image">Background image path or URL<input name="image" value="${esc(c.image||'')}" placeholder="images/shoes.jpg or paste URL"><input type="file" accept="image/*" data-category-upload><small>Landscape image recommended: 1200 &times; 900 px. Uploads are optimized in your browser.</small></label><div class="home-category-preview">${c.image?`<img src="${esc(c.image)}" alt="Preview">`:'<span>Image preview: matching product photo used when available</span>'}</div></div></article>`;return `<div class="admin-title"><div><span class="eyebrow">STOREFRONT CONTROL</span><h1>Home categories</h1><p>Choose which category cards appear in Find Your Style. Start with four; add or remove cards any time.</p></div></div><form id="home-categories-form" class="admin-settings-form"><div id="home-category-list">${cats.map((c,i)=>row(c,i)).join('')}</div><div class="home-category-actions"><button type="button" class="btn secondary small" data-category-add>+ Add category</button><span class="muted">Use the up and down arrows to set the order.</span></div><button class="btn" type="submit">Save homepage categories</button></form>`;}

  function homeSlideshowAdmin(){let slides=getCarouselSlides(),productOptions=products.filter(p=>p.active!==false).map(p=>`<option value="product.html?id=${encodeURIComponent(p.id)}">${esc(p.name)}</option>`).join('');return `<div class="admin-title"><div><span class="eyebrow">STOREFRONT CONTROL</span><h1>Homepage slideshow</h1><p>Manage image-only homepage slides. Upload an image and choose which product or page opens when customers click it.</p></div></div><form id="home-slideshow-form" class="admin-settings-form"><div id="home-slide-list">${slides.map((slide,i)=>`<article class="home-slide-editor"><header><b>Slide ${i+1}</b><div><button type="button" class="carousel-remove-slide" data-slide-up>&#8593;</button> <button type="button" class="carousel-remove-slide" data-slide-down>&#8595;</button> <button type="button" class="carousel-remove-slide" data-slide-remove ${slides.length===1?'disabled':''}>Remove</button></div></header><div class="home-slide-fields"><label class="home-slide-image">Slide image<input name="image" value="${esc(slide.image||'')}" required placeholder="Image path or URL"><input type="file" accept="image/*" data-slide-upload><small>Recommended 1600 &times; 500 px (wide landscape). Uploads are optimized before saving.</small></label><div class="home-slide-preview">${slide.image?`<img src="${esc(slide.image)}" alt="Slide preview">`:'<span>Upload or add an image path</span>'}</div><label>Link to product<select data-slide-product><option value="">Use custom page link</option>${productOptions}</select><input name="link" value="${esc(slide.link||'shop.html')}" required placeholder="product.html?id=product-id"></label></div></article>`).join('')}</div><div class="home-category-actions"><button type="button" class="btn secondary small" data-slide-add>+ Add slide</button><span class="muted">Use the arrows to reorder slides. The slideshow changes automatically.</span></div><button class="btn" type="submit">Save homepage slideshow</button></form>`;}

  function pageProductsAdmin(){let saved=read('sazPageProducts',{}),key=pageProductSections.some(([id])=>id===selectedProductPage)?selectedProductPage:'homeFeatured',ids=Array.isArray(saved[key])?saved[key]:defaultPageProductIds(key),checked=new Set(ids);return `<div class="admin-title"><div><span class="eyebrow">STOREFRONT CONTROL</span><h1>Page products</h1><p>Choose exactly which active products appear in each storefront section or collection.</p></div></div><form id="page-products-form"><div class="page-products-toolbar"><label>Choose a page or section<select id="page-products-section" name="section">${pageProductSections.map(([id,label])=>`<option value="${id}" ${id===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="page-products-search">Find a product<input id="page-products-search" type="search" placeholder="Search product names or categories"></label><div class="page-products-bulk"><button type="button" class="btn secondary small" data-page-products="all">Select all</button><button type="button" class="btn secondary small" data-page-products="none">Clear all</button></div></div><div class="page-products-list">${products.filter(p=>p.active!==false).map(p=>{let image=p.images?.[0]||p.image||'';return `<label class="page-product-row"><input type="checkbox" name="productIds" value="${esc(p.id)}" ${checked.has(p.id)?'checked':''}><span class="page-product-thumb">${image?`<img src="${esc(image)}" alt="">`:'<i>SAZ</i>'}</span><span class="page-product-name"><b>${esc(p.name)}</b><small>${esc(p.category||'Uncategorized')} · ${money(p.price)}</small></span><span class="page-product-state">Show in section</span></label>`;}).join('')||'<p class="empty">Add active products in the catalog first.</p>'}</div><footer class="page-products-footer"><span class="muted">Selections save separately for each page or section.</span><button class="btn" type="submit">Save placement</button></footer></form>`;}
  const typeOptions = selected => productTypes.map(t=>`<option value="${esc(t)}" ${selected===t?'selected':''}>${esc(t)}</option>`).join('')+`<option value="__other__" ${productTypes.includes(selected)?'':'selected'}>Other…</option>`;
  const typeRows = () => productTypes.map(t=>`<div><span>${esc(t)}</span><button type="button" class="admin-row-action danger" data-type="${esc(t)}" onclick="event.stopPropagation();this.dispatchEvent(new CustomEvent('remove-product-type',{bubbles:true,detail:this.dataset.type}))">Remove</button></div>`).join('');
  function compressProductImage(file){return new Promise((resolve,reject)=>{let reader=new FileReader(),img=new Image();reader.onerror=reject;reader.onload=()=>{img.onload=()=>{let scale=Math.min(1,1500/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',.78));};img.onerror=reject;img.src=reader.result;};reader.readAsDataURL(file);});}
  const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function artBase(p, extra=''){if(!['tee','hoodie','cap','jacket','pants','bag'].includes(p.type))p={...p,type:'tee'};let body='';if(p.type==='tee')body='<path d="M80 48 115 28 135 48 157 36 194 68 175 91 160 80 160 211 92 211 92 80 77 91 58 68z" fill="#101318" stroke="#20242a" stroke-width="3"/><path d="M116 29q14 19 28 0" fill="none" stroke="#56606a" stroke-width="3"/>';
    if(p.type==='hoodie')body='<path d="M93 58q27-43 54 0l38 22 18 53-22 9-14-30v104H74V112l-14 30-22-9 18-53z" fill="#111419" stroke="#242a31" stroke-width="3"/><path d="M93 58q27 23 54 0l-5 40h-44z" fill="#0b0e12" stroke="#383f46" stroke-width="3"/><path d="M115 92v13m10-13v13" stroke="#89909a" stroke-width="2"/>';
    if(p.type==='cap')body='<path d="M54 143q4-63 67-72 58 4 71 72-42-18-138 0z" fill="#101318" stroke="#30363e" stroke-width="3"/><path d="M53 143q62-19 143 0-17 27-74 25-52-1-69-25z" fill="#161b22" stroke="#30363e" stroke-width="3"/><path d="M117 74v48" stroke="#30363e" stroke-width="2"/>';
    if(p.type==='jacket')body='<path d="M88 48 115 29h32l29 19 29 24-17 30-18-13v108H76V89l-18 13-17-30z" fill="#11161b" stroke="#29313a" stroke-width="3"/><path d="M115 30l16 18 16-18m-16 18v157" fill="none" stroke="#424951" stroke-width="3"/><path d="M91 143h19m37 0h19" stroke="#636c76" stroke-width="3"/>';
    if(p.type==='pants')body='<path d="M78 43h92l-9 165h-43l-7-102-8 102H59z" fill="#11161b" stroke="#30363e" stroke-width="3"/><path d="M79 44h90m-53 1-4 63m-8 8H78m74-8v9" stroke="#505761" stroke-width="3"/>';
    if(p.type==='bag')body='<path d="M69 82q0-41 47-41t47 41v113H69z" fill="#11161b" stroke="#30363e" stroke-width="3"/><path d="M96 80V60q20-26 40 0v20M79 123h74v50H79z" fill="#171d24" stroke="#414851" stroke-width="3"/><path d="M91 124v25h50v-25" fill="none" stroke="#4a535d" stroke-width="3"/>';
     let imageSrc=p.image||p.images?.[0];if(imageSrc)return `<div class="product-art ${extra}"><img src="${esc(imageSrc)}" alt="${esc(p.name)}" loading="${page==='product'&&p.id===selected?'eager':'lazy'}" decoding="async" style="width:100%;height:100%;object-fit:cover">${p.badge?`<span class="tag">${esc(p.badge)}</span>`:''}<button class="favorite ${wish.includes(p.id)?'active':''}" data-action="wish" data-id="${esc(p.id)}" aria-label="Add to wishlist">${wish.includes(p.id)?'♥':'♡'}</button></div>`;
     return `<div class="product-art ${extra}"><svg viewBox="0 0 250 240" role="img" aria-label="${p.name}"><ellipse cx="125" cy="213" rx="74" ry="9" fill="#000" opacity=".18"/>${body}<path d="M106 121l19-12 20 12-6 8 12-5 12 13-18 6-10-7v19h-18v-19l-10 7-18-6 12-13 12 5z" fill="#e64e38"/><path d="M125 109l20 12-6 8-14-8z" fill="#63d9bf"/><text x="125" y="169" text-anchor="middle" fill="#dfe6e6" font-size="11" font-family="sans-serif" letter-spacing="3">S A Z</text><text x="125" y="181" text-anchor="middle" fill="#bac1c5" font-size="6" font-family="sans-serif" letter-spacing="4">HOUSE</text></svg>${p.badge?`<span class="tag">${p.badge}</span>`:''}<button class="favorite ${wish.includes(p.id)?'active':''}" data-action="wish" data-id="${p.id}" aria-label="Add to wishlist">${wish.includes(p.id)?'♥':'♡'}</button></div>`; }
  function getTotals(city){const sub=cart.reduce((n,x)=>n+product(x.id).price*x.qty,0),s=getSettings(),chosen=city??document.querySelector('[name="city"]')?.value??'',dhaka=chosen.toLowerCase()==='dhaka';let shipping=dhaka?Number(s.dhaka)||0:Number(s.outside)||0;if(Number(s.freeThreshold)>0&&sub>=Number(s.freeThreshold))shipping=0;let discount=0,code=read('sazCouponCode',''),coupon=read('sazCoupons',[]).find(c=>c.code===code&&c.active&&sub>=Number(c.minimum||0));if(coupon)discount=coupon.type==='percent'?Math.min(sub,Math.round(sub*coupon.value/100)):Math.min(sub,Number(coupon.value));return {sub,shipping,discount,total:Math.max(0,sub+shipping-discount),coupon:coupon?.code||''};}
  function summary(){let t=getTotals(),s=getSettings();return `<aside class="summary"><h3>Order Summary</h3><div class="summary-row"><span>Subtotal</span><span>${money(t.sub)}</span></div><div class="summary-row"><span>Delivery</span><span>${t.shipping?money(t.shipping):'FREE'}</span></div>${t.discount?`<div class="summary-row"><span>Coupon ${esc(t.coupon)}</span><span>−${money(t.discount)}</span></div>`:''}<div class="summary-row total"><span>Total</span><span>${money(t.total)}</span></div><small class="muted">${Number(s.freeThreshold)>0?`Free delivery over ${money(s.freeThreshold)}.`:'Delivery price depends on your location.'}</small></aside>`;}
  function faq(){const qs=[['How long does shipping take?','Dhaka orders usually arrive in 1–3 business days. Other districts take 3–5 business days. We will contact you with delivery details.'],['Do you ship outside Bangladesh?','Our current delivery service covers all 64 districts of Bangladesh.'],['What is your return policy?','Unused items with original tags can be returned within 7 days of delivery. Contact our support team to arrange a return.'],['How can I track my order?','After placing your order, our team will confirm it by phone. Contact support with your phone number if you need an update.'],['What payment methods do you accept?','We accept cash on delivery and mobile banking. Card selection is shown as a demo and does not process a real payment.'],['Are the products original?','Yes. Every item is designed and sold by SAZ House.'],['How do I choose the right size?','Check the size guide on each product page. If you are between sizes, we recommend choosing the larger size.']];return `<main class="wrap page"><div class="breadcrumbs"><a href="index.html">Home</a>　›　FAQ</div><span class="eyebrow">Help center</span><h1 class="page-title">Frequently Asked Questions</h1><p class="muted">Find answers to common questions about our products, shipping, returns and orders.</p><div style="max-width:820px;margin:24px auto">${qs.map(([q,a])=>`<div class="faq-item"><button class="faq-question" data-action="faq">${q}<span>＋</span></button><div class="faq-answer">${a}</div></div>`).join('')}</div><div class="banner"><div><h2>Still need help?</h2><p class="muted">Our team is happy to help.</p></div><a class="btn" href="contact.html">CONTACT US →</a></div></main>`;}
  function account(){const user=read('sazUser',null);if(!user)return `<main class="wrap page"><div class="breadcrumbs">Home　›　My Account</div><div style="max-width:460px;margin:25px auto"><span class="eyebrow">Welcome back</span><h1 class="page-title">My Account</h1><p class="muted">Sign in to view your demo account and orders.</p><form class="form-card" id="login-form"><div class="field"><label>Email</label><input name="email" type="email" required placeholder="you@example.com"></div><div class="field" style="margin:13px 0"><label>Password</label><input name="password" type="password" required minlength="4" placeholder="At least 4 characters"></div><button class="btn">SIGN IN →</button><p class="muted">Demo only. Any valid email and 4+ character password will sign in locally.</p></form></div></main>`;let orders=read('sazOrders',[]);return `<main class="wrap page"><div class="breadcrumbs">Home　›　My Account</div><div class="account-layout"><aside class="side-nav"><button class="active" data-action="account-tab" data-tab="Dashboard">Dashboard</button><button data-action="account-tab" data-tab="My Orders">My Orders</button><button data-action="account-tab" data-tab="Wishlist">Wishlist (${wish.length})</button><button data-action="account-tab" data-tab="Account Settings">Account Settings</button><button data-action="logout">Log out</button></aside><section id="account-content"><span class="eyebrow">My account</span><h1 class="page-title">Dashboard</h1><p class="muted">Welcome, ${user.email}!</p><div class="stats"><div class="stat"><small>Total orders</small><strong>${orders.length}</strong></div><div class="stat"><small>Wishlist items</small><strong>${wish.length}</strong></div><div class="stat"><small>Reward points</small><strong>${orders.length*50}</strong></div></div><h2 style="font:600 20px 'Space Grotesk';margin-top:28px">Recent Orders</h2>${orders.length?orders.map(o=>`<div class="cart-item"><div class="cart-item-main"><b>${o.ref}</b><p>${o.date} · ${o.items} item(s)</p></div><b>${money(o.total)}</b><span class="eyebrow">${o.status}</span></div>`).join(''):'<p class="muted">No orders yet. <a class="textlink" href="shop.html">Start shopping →</a></p>'}</section></div></main>`;}
  function adminContentBase(view='Overview'){
    const orders=read('sazOrders',[]),messages=read('sazMessages',[]),revenue=orders.filter(o=>o.status!=='Cancelled').reduce((n,o)=>n+o.total,0);
    if(view==='Orders')return `<div class="admin-title"><div><span class="eyebrow">SALES MANAGEMENT</span><h1>Orders</h1><p>Review customer orders and update fulfillment status.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>DATE</th><th>ITEMS</th><th>TOTAL</th><th>STATUS</th></tr></thead><tbody>${orders.length?orders.map((o,i)=>`<tr><td><b>${o.ref}</b></td><td>${o.customer||'Customer'}</td><td>${o.date}</td><td>${o.items}</td><td>${money(o.total)}</td><td><select data-action="order-status" data-index="${i}" aria-label="Order status"><option ${o.status==='Processing'?'selected':''}>Processing</option><option ${o.status==='Shipped'?'selected':''}>Shipped</option><option ${o.status==='Delivered'?'selected':''}>Delivered</option><option ${o.status==='Cancelled'?'selected':''}>Cancelled</option></select></td></tr>`).join(''):`<tr><td colspan="6" class="admin-empty">No orders yet. Store orders will appear here.</td></tr>`}</tbody></table></div>`;
    if(view==='Products')return `<div class="admin-title admin-title-action"><div><span class="eyebrow">CATALOG MANAGEMENT</span><h1>Products</h1><p>Add products and manage price, stock, sizes and media.</p></div><button class="btn" data-action="product-new">＋ Add product</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>PRICE</th><th>STOCK</th><th>SIZES</th><th>ACTIONS</th></tr></thead><tbody>${products.length?products.map(p=>`<tr><td><div class="admin-product-cell">${p.image?`<img src="${esc(p.image)}" alt="">`:`<span class="admin-product-thumb">${esc((p.name||'?')[0])}</span>`}<span><b>${esc(p.name)}</b><small>${esc(p.color||'')}</small></span></div></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${Number(p.stock)||0}</td><td>${esc((p.sizes||[]).join(', ')||'—')}</td><td><button class="admin-row-action" data-action="product-edit" data-id="${esc(p.id)}">Edit</button><button class="admin-row-action danger" data-action="product-delete" data-id="${esc(p.id)}">Remove</button></td></tr>`).join(''):`<tr><td colspan="6" class="admin-empty">No products. Add your first product.</td></tr>`}</tbody></table></div>`;
    if(view==='Messages')return `<div class="admin-title"><div><span class="eyebrow">CUSTOMER CARE</span><h1>Messages</h1><p>Messages submitted through the contact page.</p></div></div>${messages.length?messages.map(m=>`<article class="admin-message"><div><b>${m.subject}</b><small>${m.name} · ${m.email} · ${new Date(m.date).toLocaleDateString()}</small></div><p>${m.message}</p></article>`).join(''):`<div class="admin-empty-card">No messages yet. New contact form submissions will appear here.</div>`}`;
    if(view==='Coupons') {let coupons=read('sazCoupons',[]);return `<div class="admin-title admin-title-action"><div><span class="eyebrow">PROMOTIONS</span><h1>Coupons</h1><p>Create discounts customers can use at checkout.</p></div><button class="btn" data-action="coupon-new">＋ Add coupon</button></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CODE</th><th>DISCOUNT</th><th>MINIMUM CART</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${coupons.length?coupons.map(c=>`<tr><td><b>${esc(c.code)}</b></td><td>${c.type==='percent'?`${c.value}%`:`${money(c.value)} off`}</td><td>${money(c.minimum||0)}</td><td>${c.active?'Active':'Paused'}</td><td><button class="admin-row-action" data-action="coupon-edit" data-code="${esc(c.code)}">Edit</button><button class="admin-row-action danger" data-action="coupon-delete" data-code="${esc(c.code)}">Remove</button></td></tr>`).join(''):`<tr><td colspan="5" class="admin-empty">No coupons created.</td></tr>`}</tbody></table></div>`;}
    if(view==='Settings'){let s=getSettings();return `<div class="admin-title"><div><span class="eyebrow">STORE CONFIGURATION</span><h1>Store settings</h1><p>Set delivery pricing and the payment methods customers can choose.</p></div></div><form id="settings-form" class="admin-settings-form"><section class="admin-panel"><h2>Delivery charges</h2><div class="admin-form-grid"><label>Inside Dhaka (৳)<input name="dhaka" type="number" min="0" value="${Number(s.dhaka)}" required></label><label>Outside Dhaka (৳)<input name="outside" type="number" min="0" value="${Number(s.outside)}" required></label><label>Free delivery threshold (৳)<input name="freeThreshold" type="number" min="0" value="${Number(s.freeThreshold)}" required><small>Set 0 to disable free delivery.</small></label></div></section><section class="admin-panel"><h2>Payment methods</h2><div class="admin-payment-grid"><label><input type="checkbox" name="cod" ${s.payments.cod?'checked':''}> Cash on delivery</label><label><input type="checkbox" name="bkash" ${s.payments.bkash?'checked':''}> bKash</label><label><input type="checkbox" name="nagad" ${s.payments.nagad?'checked':''}> Nagad</label><label><input type="checkbox" name="card" ${s.payments.card?'checked':''}> Card (demo)</label></div><div class="admin-form-grid"><label>bKash merchant / payment number<input name="bkashNumber" value="${esc(s.bkashNumber||'')}" placeholder="01XXXXXXXXX"></label><label>Nagad merchant / payment number<input name="nagadNumber" value="${esc(s.nagadNumber||'')}" placeholder="01XXXXXXXXX"></label></div></section><button class="btn" type="submit">Save store settings</button></form>`;}
    if(view==='Site Content'){let c=getSiteContent();return `<div class="admin-title"><div><span class="eyebrow">NO-CODE EDITOR</span><h1>Site content</h1><p>Edit the storefront text and contact details here, then save to publish locally.</p></div></div><form id="site-content-form" class="admin-settings-form"><section class="admin-panel"><h2>Branding & announcement</h2><div class="admin-form-grid"><label class="admin-field-full">Logo file path or URL<input name="logoPath" value="${esc(c.logoPath)}" placeholder="logo.png"><small>Recommended logo: 500 × 500 px, transparent PNG or SVG.</small></label><label class="admin-field-full">Announcement bar text<input name="announcement" value="${esc(c.announcement)}"></label><label class="admin-field-full">Footer description<textarea name="footerText" rows="2">${esc(c.footerText)}</textarea></label></div></section><section class="admin-panel"><h2>About and contact details</h2><div class="admin-form-grid"><label class="admin-field-full">About story<textarea name="aboutStory" rows="4">${esc(c.aboutStory)}</textarea></label><label>Contact email<input name="contactEmail" type="email" value="${esc(c.contactEmail)}"></label><label>Contact phone<input name="contactPhone" value="${esc(c.contactPhone)}"></label><label class="admin-field-full">Store location<input name="contactLocation" value="${esc(c.contactLocation)}"></label></div></section><button class="btn" type="submit">Save and publish content</button></form>`;}
    if(view==='Statistics'){let paid=orders.filter(o=>o.status!=='Cancelled'),sold=paid.reduce((n,o)=>n+(o.items||0),0),average=paid.length?paid.reduce((n,o)=>n+o.total,0)/paid.length:0;let counts={Processing:0,Shipped:0,Delivered:0,Cancelled:0};orders.forEach(o=>counts[o.status]=(counts[o.status]||0)+1);let monthly={};paid.forEach(o=>{let d=new Date(o.createdAt||o.date);let key=isNaN(d)?'Other':d.toLocaleString('en',{month:'short',year:'numeric'});monthly[key]=(monthly[key]||0)+o.total;});return `<div class="admin-title"><div><span class="eyebrow">STORE PERFORMANCE</span><h1>Statistics</h1><p>Totals calculated from orders stored in this browser.</p></div></div><div class="admin-stats"><article><small>Completed & active sales</small><strong>${money(paid.reduce((n,o)=>n+o.total,0))}</strong><span>Cancelled orders excluded</span></article><article><small>Orders</small><strong>${paid.length}</strong><span>${counts.Cancelled} cancelled</span></article><article><small>Items sold</small><strong>${sold}</strong><span>From saved orders</span></article><article><small>Average order</small><strong>${money(average)}</strong><span>Per non-cancelled order</span></article></div><div class="admin-overview-grid"><section class="admin-panel"><h2>Order status</h2>${Object.entries(counts).map(([k,v])=>`<div class="admin-stat-row"><span>${k}</span><b>${v}</b></div>`).join('')}</section><section class="admin-panel"><h2>Sales by month</h2>${Object.entries(monthly).length?Object.entries(monthly).map(([k,v])=>`<div class="admin-stat-row"><span>${esc(k)}</span><b>${money(v)}</b></div>`).join(''):'<div class="admin-empty-card">Monthly sales appear after orders are placed.</div>'}</section></div>`;}
    return `<div class="admin-title"><div><span class="eyebrow">STORE MANAGEMENT</span><h1>Overview</h1><p>Here’s what’s happening at SAZ House.</p></div></div><div class="admin-stats"><article><small>Products</small><strong>${products.length}</strong><span>In the catalog</span></article><article><small>Orders</small><strong>${orders.length}</strong><span>All time</span></article><article><small>Sales total</small><strong>${money(revenue)}</strong><span>From demo orders</span></article><article><small>Messages</small><strong>${messages.length}</strong><span>Customer enquiries</span></article></div><div class="admin-overview-grid"><section class="admin-panel"><div class="admin-panel-head"><h2>Recent orders</h2><button data-action="admin-tab" data-view="Orders">View all →</button></div>${orders.length?orders.slice(0,5).map(o=>`<div class="admin-recent"><div><b>${o.ref}</b><small>${o.customer||'Customer'} · ${o.date}</small></div><strong>${money(o.total)}</strong><span class="admin-status">${o.status}</span></div>`).join(''):`<div class="admin-empty-card">New store orders will show here.</div>`}</section><section class="admin-panel admin-shortcuts"><h2>Quick links</h2><button data-action="admin-tab" data-view="Products">▦　Manage products <span>→</span></button><button data-action="admin-tab" data-view="Messages">✉　Read messages <span>→</span></button><a href="index.html">↗　Open storefront</a></section></div>`;
  }
  function adminContent(view='Overview'){if(view==='Homepage slideshow')return homeSlideshowAdmin();if(view==='Home categories')return homeCategoryEditor();if(view==='Page products')return pageProductsAdmin();if(view!=='Orders')return adminContentBase(view);let orders=read('sazOrders',[]);return `<div class="admin-title"><div><span class="eyebrow">SALES MANAGEMENT</span><h1>Orders</h1><p>Review customer details, delivery destination, payment and fulfillment status.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ORDER</th><th>CUSTOMER / DELIVERY DETAILS</th><th>ITEMS</th><th>PAYMENT</th><th>TOTAL</th><th>STATUS</th></tr></thead><tbody>${orders.length?orders.map((o,i)=>`<tr><td><b>${esc(o.ref)}</b><small>${esc(o.date)}</small></td><td><b>${esc(o.customer||'Customer')}</b><details class="admin-order-details"><summary>View delivery details</summary><span>${esc(o.phone||'')}</span><span>${esc(o.email||'')}</span><span>${esc(o.address||'')}</span><span>${esc([o.district,o.city,o.division].filter(Boolean).join(', '))}</span></details></td><td>${(o.lines||[]).map(x=>`${esc(x.name)} · ${esc(x.color||'')} · ${esc(x.size)} × ${x.qty}`).join('<br>')||`${o.items} item(s)`}</td><td>${esc(o.payment||'—')}</td><td>${money(o.total)}${o.discount?`<small>Coupon ${esc(o.coupon)} · −${money(o.discount)}</small>`:''}</td><td><select data-action="order-status" data-index="${i}" aria-label="Order status"><option ${o.status==='Processing'?'selected':''}>Processing</option><option ${o.status==='Shipped'?'selected':''}>Shipped</option><option ${o.status==='Delivered'?'selected':''}>Delivered</option><option ${o.status==='Cancelled'?'selected':''}>Cancelled</option></select></td></tr>`).join(''):`<tr><td colspan="6" class="admin-empty">No orders yet. Store orders will appear here.</td></tr>`}</tbody></table></div>`;}
  function couponEditor(c={}){let editing=Boolean(c.code);return `<div class="admin-modal-backdrop" data-action="modal-outside"><section class="admin-modal" onclick="event.stopPropagation()"><header><div><span class="eyebrow">PROMOTIONS</span><h2>${editing?'Edit coupon':'Create coupon'}</h2></div><button type="button" class="admin-modal-close" onclick="this.closest('.admin-modal-backdrop').remove()">×</button></header><form id="coupon-form"><input type="hidden" name="oldCode" value="${esc(c.code||'')}"><div class="admin-form-grid"><label>Coupon code *<input name="code" required value="${esc(c.code||'')}" placeholder="WELCOME10"></label><label>Discount type<select name="type"><option value="percent" ${c.type==='fixed'?'':'selected'}>Percentage</option><option value="fixed" ${c.type==='fixed'?'selected':''}>Fixed amount</option></select></label><label>Discount value *<input name="value" type="number" min="1" required value="${Number(c.value)||''}"></label><label>Minimum cart total (৳)<input name="minimum" type="number" min="0" value="${Number(c.minimum)||0}"></label><label class="admin-check"><input name="active" type="checkbox" ${c.active===false?'':'checked'}> Coupon active</label></div><footer><button type="button" class="btn secondary" onclick="this.closest('.admin-modal-backdrop').remove()">Cancel</button><button class="btn" type="submit">Save coupon</button></footer></form></section></div>`;}
  function admin(){let auth=read('sazAdmin',false);if(!auth)return `<main class="admin-login-page"><a class="admin-back" href="index.html">← Back to storefront</a><div class="admin-login-card"><img class="brand-logo" src="logo%20black%20bg.jpg" alt="SAZ House"><span class="eyebrow">SECURE AREA · DEMO</span><h1>Admin sign in</h1><p>Sign in to manage the store dashboard.</p><form id="admin-login-form"><div class="field"><label>Email address</label><input name="email" type="email" required placeholder="admin@sazhouse.com"></div><div class="field"><label>Password</label><input name="password" type="password" required placeholder="Enter password"></div><button class="btn">Sign in to dashboard <span>→</span></button></form><small class="admin-hint">Demo credentials: admin@sazhouse.com / Admin123</small></div></main>`;
    return `<main class="admin-shell"><aside class="admin-sidebar"><a class="admin-brand" href="admin.html"><img class="brand-logo" src="logo%20black%20bg.jpg" alt="SAZ House"><span>STORE ADMIN<small>MANAGEMENT PORTAL</small></span></a><div class="admin-nav-label">WORKSPACE</div><button class="admin-nav active" data-action="admin-tab" data-view="Overview"><span>◫</span> Overview</button><button class="admin-nav" data-action="admin-tab" data-view="Statistics"><span>▥</span> Statistics</button><button class="admin-nav" data-action="admin-tab" data-view="Orders"><span>▤</span> Orders <i>${read('sazOrders',[]).length}</i></button><button class="admin-nav" data-action="admin-tab" data-view="Products"><span>▦</span> Products <i>${products.length}</i></button><button class="admin-nav" data-action="admin-tab" data-view="Coupons"><span>%</span> Coupons <i>${read('sazCoupons',[]).length}</i></button><button class="admin-nav" data-action="admin-tab" data-view="Messages"><span>✉</span> Messages <i>${read('sazMessages',[]).length}</i></button><button class="admin-nav" data-action="admin-tab" data-view="Settings"><span>⚙</span> Store settings</button><div class="admin-sidebar-bottom"><a href="index.html">↗　View storefront</a><button data-action="admin-logout">⇥　Sign out</button></div></aside><section class="admin-main"><header class="admin-topbar"><div><small>SAZ HOUSE / ADMIN</small><b>Store dashboard</b></div><div class="admin-top-actions"><span class="admin-live"><i></i> DEMO MODE</span><button data-action="admin-logout">Sign out</button></div></header><div class="admin-workspace" id="admin-workspace">${adminContent()}</div></section></main>`;
  }
  function searchPage(){let term=new URLSearchParams(location.search).get('q')||'';return `<main class="wrap page"><div class="breadcrumbs"><a href="index.html">Home</a>　›　Search</div><h1 class="page-title">Search Results</h1><input class="searchbox" id="search-input" value="${term.replaceAll('"','&quot;')}" placeholder="⌕ Search products..."><p class="muted" id="search-result-label"></p><div class="grid" id="search-grid"></div></main>`;}
  function success(){let o=read('sazLastOrder',null);return `<main class="wrap page"><div class="empty" style="max-width:700px;margin:35px auto"><div class="big" style="color:var(--lime)">✓</div><span class="eyebrow">Order placed</span><h1 class="page-title" style="margin:12px 0">Thank you for your order!</h1><p class="muted">${o?`Your order <b>${o.ref}</b> is confirmed. We'll contact you with delivery updates.`:'Your order has been received.'}</p>${o?`<div class="summary" style="text-align:left;margin:22px auto;max-width:420px"><div class="summary-row"><span>Order number</span><b>${o.ref}</b></div><div class="summary-row"><span>Payment</span><b>${o.payment}</b></div><div class="summary-row total"><span>Total</span><span>${money(o.total)}</span></div></div>`:''}<a class="btn" href="shop.html">CONTINUE SHOPPING →</a> <a class="btn secondary" href="account.html">VIEW ACCOUNT</a></div></main>`;}
  function productEditor(p={}){let editing=Boolean(p.id),known=productTypes.includes(p.type||'tee'),images=p.images?.length?p.images:(p.image?[p.image]:[]);return `<div class="admin-modal-backdrop" data-action="modal-outside"><section class="admin-modal" onclick="event.stopPropagation()"><header><div><span class="eyebrow">CATALOG</span><h2>${editing?'Edit product':'Add product'}</h2></div><button type="button" class="admin-modal-close" onclick="this.closest('.admin-modal-backdrop').remove()">×</button></header><form id="product-form"><input type="hidden" name="oldId" value="${esc(p.id||'')}"><div class="admin-form-grid"><label>Product name *<input name="name" required value="${esc(p.name||'')}" placeholder="Product name"></label><label>Category *<input name="category" required value="${esc(p.category||'T-Shirts')}" placeholder="T-Shirts, Hoodies…"></label><label>Price (৳) *<input name="price" type="number" min="0" required value="${Number(p.price)||''}"></label><label>Compare-at price (৳)<input name="old" type="number" min="0" value="${Number(p.old)||''}"></label><label class="admin-field-full">Available colors (comma separated)<input name="colors" value="${esc((p.colors?.length?p.colors:[p.color||'Black']).join(', '))}" placeholder="Black, White, Navy"></label><label>Product type<select name="type">${productTypes.map(t=>`<option value="${esc(t)}" ${known&&(p.type||'tee')===t?'selected':''}>${esc(t)}</option>`).join('')}<option value="__other__" ${known?'':'selected'}>Other…</option></select><input class="custom-type-input" name="customType" value="${known?'':esc(p.type||'')}" placeholder="Enter a new product type" style="display:${known?'none':'block'}"><button type="button" class="admin-text-action" onclick="event.stopPropagation();this.dispatchEvent(new CustomEvent('open-product-types',{bubbles:true}))">Manage product types</button></label><label>Stock quantity<input name="stock" type="number" min="0" value="${p.stock??0}"></label><label>Badge (optional)<input name="badge" value="${esc(p.badge||'')}" placeholder="NEW / BEST SELLER"></label><label class="admin-field-full">Available sizes (comma separated)<input name="sizes" value="${esc((p.sizes||['S','M','L','XL']).join(', '))}" placeholder="S, M, L, XL"></label><label class="admin-field-full">Product images (one URL or local path per line)<textarea name="imageUrls" rows="3" placeholder="Paste one image URL per line">${esc(images.join('\n'))}</textarea></label><label class="admin-field-full">Upload multiple product images<input type="file" id="product-image-file" accept="image/*" multiple><small>Select several images. Recommended product image: 1200 × 1500 px (4:5 portrait). Images are resized and saved in this browser.</small></label><label class="admin-field-full">Product video URL (.mp4 / web video)<input name="video" value="${esc(p.video||'')}" placeholder="videos/product.mp4 or https://…"></label><label class="admin-field-full">Description<textarea name="description" rows="5" placeholder="Use blank lines between paragraphs and start list items with -">${esc(p.description||'')}</textarea><small>Formatting tip: blank line = new paragraph; start a line with - for a bullet.</small></label><label class="admin-check"><input name="active" type="checkbox" ${p.active===false?'':'checked'}> Visible in storefront</label></div><footer><button type="button" class="btn secondary" onclick="this.closest('.admin-modal-backdrop').remove()">Cancel</button><button class="btn" type="submit">${editing?'Save changes':'Create product'}</button></footer></form></section></div>`;}
  function typeManager(){return `<div class="admin-modal-backdrop type-manager-backdrop" data-action="modal-outside"><section class="admin-modal type-manager" onclick="event.stopPropagation()"><header><div><span class="eyebrow">PRODUCT CATALOG</span><h2>Manage product types</h2></div><button type="button" class="admin-modal-close" onclick="this.closest('.admin-modal-backdrop').remove()">×</button></header><p class="muted">Add a type to make it available in the product form. Removing a type changes products using it to “other”.</p><form id="product-type-form" class="type-add-form"><input name="typeName" required placeholder="New type, e.g. Denim"><button class="btn small" type="submit">Add type</button></form><p id="product-type-message" class="type-message"></p><div class="type-list">${typeRows()}</div></section></div>`;}
  function header(){let c=getSiteContent(),menu=(label,groups)=>`<details class="nav-item"><summary>${label}<span aria-hidden="true">⌄</span></summary><div class="mega-menu">${groups.map(([heading,items])=>`<section class="mega-group"><h3>${heading}</h3>${items.map(([text,url])=>{let target=['Men','Women'].includes(label)?url.replace('shop.html?','shop.html?department='+label.toLowerCase()+'&'):url;return `<a href="${target}">${text}</a>`;}).join('')}</section>`).join('')}</div></details>`;return `<div class="topbar">${esc(c.announcement)}</div><header class="header"><div class="wrap nav"><button class="iconbtn menu-toggle" data-action="menu" aria-label="Open menu">☰</button>${logo}<nav class="links" id="navlinks"><a class="nav-home" href="index.html">Home</a>${menu('Men', [['Clothing', [['Shop all men','shop.html?sort=featured'],['T-Shirts','shop.html?category=T-Shirts'],['Shirts','shop.html?category=Shirts'],['Hoodies','shop.html?category=Hoodies'],['Pants','shop.html?category=Pants'],['Jackets','shop.html?category=Jackets']]],[ 'More for men', [['Shoes','shop.html?category=Shoes'],['Bags','shop.html?category=Bags'],['Accessories','shop.html?category=Accessories']]]])}${menu('Women', [['Clothing', [['Shop all women','shop.html?sort=featured'],['Dresses','shop.html?category=Dresses'],['Shirts','shop.html?category=Shirts'],['Tops','shop.html?category=Tops'],['Hoodies','shop.html?category=Hoodies'],['Pants','shop.html?category=Pants'],['Jackets','shop.html?category=Jackets']]],[ 'More for women', [['Shoes','shop.html?category=Shoes'],['Bags','shop.html?category=Bags'],['Accessories','shop.html?category=Accessories']]]])}${menu('New Arrivals', [['Men', [['Shop men','shop.html?department=men&sort=newest']]],[ 'Women', [['Shop women','shop.html?department=women&sort=newest']]],[ 'Latest products', [['View latest','shop.html?sort=newest']]]])}${menu('Collections', [['Discover', [['Trending','shop.html?collection=trending'],['Premium collection','shop.html?collection=premium'],['Casual collection','shop.html?collection=casual'],['Gift collection','shop.html?collection=gifts']]]])}${menu('Sale', [['Shop sale', [['Men','shop.html?department=men&sort=sale'],['Women','shop.html?department=women&sort=sale'],['All sale','shop.html?sort=sale']]]])}${menu('About', [['SAZ House', [['Our story','about.html'],['Our brand','about.html'],['Contact','contact.html']]]])}${menu('More', [['Customer care', [['Size guide','faq.html'],['Shipping & delivery','faq.html'],['Returns & exchange','faq.html'],['Track order','account.html'],['FAQ','faq.html'],['Privacy policy','faq.html']]]])}</nav><div class="nav-actions"><button class="iconbtn" data-action="search" aria-label="Search">⌕</button><a href="account.html" aria-label="Account">♙</a><a class="iconbtn" href="cart.html" aria-label="Shopping bag">♧<span class="badge" id="cart-count">${count()}</span></a></div></div></header>`;}
  function footer(){let c=getSiteContent(),benefits=`<div class="benefits footer-benefits"><div class="benefit"><i>♧</i><div><b>Fast & reliable shipping</b><small>Across Bangladesh</small></div></div><div class="benefit"><i>♢</i><div><b>Secure payment</b><small>Safe checkout options</small></div></div><div class="benefit"><i>↻</i><div><b>Easy returns</b><small>7-day return policy</small></div></div><div class="benefit"><i>☏</i><div><b>Customer support</b><small>We're here to help</small></div></div></div>`;return `<footer class="footer"><div class="wrap">${benefits}<div class="footer-cols"><div>${logo}<p class="muted">${esc(c.footerText)}</p><a href="shop.html" class="btn small">Explore collection →</a></div><div><h4>Quick links</h4><a href="shop.html">Shop all</a><a href="about.html">Our story</a><a href="contact.html">Contact</a><a href="faq.html">FAQs</a></div><div><h4>Customer care</h4><a href="faq.html">Shipping & delivery</a><a href="faq.html">Returns & refunds</a><a href="account.html">My account</a><a href="contact.html">Get support</a></div><div><h4>Stay connected</h4><p class="muted">Follow SAZ House for new drops and everyday style.</p><a class="facebook-link" href="https://www.facebook.com/Sazhouse?mibextid=wwXIfr&rdid=qX9ZMvQdfThS0JNF&share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2F1CRf6deCsg%2F%3Fmibextid%3DwwXIfr" target="_blank" rel="noopener noreferrer">Facebook</a><a href="#" data-action="social">Instagram</a><a href="#" data-action="social">YouTube</a><a class="facebook-qr" href="https://www.facebook.com/Sazhouse?mibextid=wwXIfr&rdid=qX9ZMvQdfThS0JNF&share_url=https%3A%2F%2Fwww.facebook.com%2Fshare%2F1CRf6deCsg%2F%3Fmibextid%3DwwXIfr" target="_blank" rel="noopener noreferrer"><img src="saz_house_facebook_branded_qr.png" alt="Scan to visit SAZ House on Facebook"><span>Scan to follow us</span></a></div></div><div class="copyright"><span>© 2026 SAZ House. All rights reserved.</span><span>Dhaka, Bangladesh · Privacy · Terms</span></div></div></footer>`;}
  function about(){let c=getSiteContent();return `<main class="wrap page"><section class="banner"><div><span class="eyebrow">Our story</span><h1 class="page-title">About SAZ House</h1><p class="muted">More than just clothes. It's a movement.</p></div><div style="font-size:72px">⚡</div></section><section class="section" style="max-width:780px"><h2>Built for the bold</h2><p class="muted site-story">${esc(c.aboutStory)}</p><h2 style="margin-top:30px">Our values</h2><div class="benefits"><div class="benefit"><i>◇</i><div><b>Quality first</b><small>Made to last</small></div></div><div class="benefit"><i>◎</i><div><b>Community driven</b><small>For every body</small></div></div><div class="benefit"><i>♧</i><div><b>Everyday design</b><small>Made to move</small></div></div><div class="benefit"><i>✦</i><div><b>Own your style</b><small>Be yourself</small></div></div></div><a class="btn" href="shop.html">SHOP THE COLLECTION →</a></section></main>`;}
  function contact(){let c=getSiteContent();return `<main class="wrap page"><div class="breadcrumbs"><a href="index.html">Home</a>　›　Contact</div><span class="eyebrow">We're here to help</span><h1 class="page-title">Get in Touch</h1><p class="muted">We'd love to hear from you. Send us a message and we'll get back to you soon.</p><div class="contact-layout" style="margin-top:25px"><div><div class="contact-card"><b>✉ Email</b><span class="muted">${esc(c.contactEmail)}</span></div><div class="contact-card"><b>☎ Phone</b><span class="muted">${esc(c.contactPhone)}</span></div><div class="contact-card"><b>⌖ Location</b><span class="muted">${esc(c.contactLocation)}</span></div><p class="muted">Support hours: Saturday–Thursday, 10am–6pm</p></div><form id="contact-form" class="form-card"><div class="form-grid"><div class="field"><label>Name</label><input name="name" required placeholder="Your name"></div><div class="field"><label>Email</label><input name="email" type="email" required placeholder="you@example.com"></div><div class="field full"><label>Subject</label><input name="subject" required placeholder="How can we help?"></div><div class="field full"><label>Message</label><textarea name="message" rows="5" required placeholder="Write your message..."></textarea></div></div><button class="btn" type="submit">SEND MESSAGE →</button><p id="contact-notice" class="notice" style="display:none">Thanks! Your message has been saved on this device.</p></form></div></main>`;}
  function art(p,extra=''){let all=p.images?.length?p.images:(p.image?[p.image]:[]),images=(page==='product'&&p.id===selected&&p.variantImages?.[chosenColor])||all;galleryIndex=Math.min(galleryIndex,Math.max(0,images.length-1));let imageSrc=images[galleryIndex]||images[0];let main=artBase({...p,image:imageSrc},extra);if(page!=='product'||p.id!==selected||images.length<2)return main;return `<div class="product-gallery"><div id="gallery-main">${main}</div><div class="product-thumbs">${images.map((src,i)=>`<button type="button" class="gallery-thumb ${i===galleryIndex?'selected':''}" data-action="gallery-image" data-index="${i}" aria-label="View product image ${i+1}"><img src="${esc(src)}" alt=""></button>`).join('')}</div></div>`;}
  function card(p){if(p.active===false)return '';return `<article class="card"><a href="product.html?id=${encodeURIComponent(p.id)}" aria-label="View ${esc(p.name)}">${art(p)}<div class="card-info"><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${esc(p.color||'Black')}</p><div class="price-row"><span class="price">${money(p.price)}${p.old?`<span class="old">${money(p.old)}</span>`:''}</span><span class="rating">★★★★★</span></div></div></a><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 13px 13px"><button class="btn small secondary" style="margin:0" data-action="buy" data-id="${esc(p.id)}">BUY NOW</button><button class="btn small" style="margin:0" data-action="add" data-id="${esc(p.id)}">＋ ADD TO CART</button></div></article>`;}
  function shop(){const cat=new URLSearchParams(location.search).get('category');if(cat&&cat!=='Collections')activeFilter=cat;let categories=['All Products',...new Set(products.filter(p=>p.active!==false).map(p=>p.category))];return `<main class="wrap page"><div class="breadcrumbs"><a href="index.html">Home</a>　›　Shop</div><section class="banner" style="padding:23px 30px;margin-bottom:24px"><div><span class="eyebrow">The collection</span><h2>Shop All</h2><p class="muted">Premium streetwear for every part of your journey.</p></div><div style="font-size:50px">🧥</div></section><div class="shop-layout"><aside class="filters" id="filters"><div class="filter-group"><h4>Categories</h4>${categories.map(n=>`<label><input type="radio" name="category" value="${esc(n)}" ${activeFilter===n?'checked':''}> ${esc(n)}</label>`).join('')}</div><div class="filter-group"><h4>Price Range <small id="price-label">৳0 – ৳4,000</small></h4><input type="range" min="0" max="50000" value="50000" id="price-range"></div><div class="filter-group"><h4>Size</h4>${['S','M','L','XL','XXL','One Size'].map(n=>`<label><input type="checkbox" class="size-filter" value="${n}"> ${n}</label>`).join('')}</div><button class="btn secondary small" data-action="clear-filter">Clear filters</button></aside><div><div class="toolbar"><button class="btn secondary small" data-action="filters">☷ Filters</button><span class="muted" id="result-count"></span><select id="sort"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="name">Name</option></select></div><div class="grid" id="shop-grid"></div><p id="no-results" class="empty" style="display:none">No products match those filters.</p></div></div></main>`;}
  function checkout(){if(!cart.length)return `<main class="wrap page"><div class="empty"><h2>No items to check out</h2><a class="btn" href="shop.html">Shop now</a></div></main>`;let s=getSettings(),methods=[['cod','Cash on Delivery'],['bkash','bKash'],['nagad','Nagad'],['card','Card (demo)']].filter(([key])=>s.payments[key]);if(!methods.length)methods=[['cod','Cash on Delivery']];return `<main class="wrap page"><div class="breadcrumbs"><a href="cart.html">Cart</a>　›　Checkout</div><h1 class="page-title">Checkout</h1><div class="steps"><div class="step active">1　Shipping</div><div class="step">2　Payment</div><div class="step">3　Review</div></div><div class="checkout-layout"><form id="checkout-form"><div class="form-card"><h3>Shipping Information</h3><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required placeholder="Your full name"></div><div class="field"><label>Phone number</label><input name="phone" required pattern="[0-9+() -]{7,}" placeholder="01XXXXXXXXX"></div><div class="field full"><label>Address</label><textarea name="address" required rows="4" placeholder="House, road, area"></textarea></div></div></div><div class="form-card"><h3>Payment Method</h3>${methods.map(([key,label],i)=>`<label class="radio"><input type="radio" name="payment" value="${label}" ${i===0?'checked':''}> ${label}${key==='bkash'&&s.bkashNumber?` · ${esc(s.bkashNumber)}`:''}${key==='nagad'&&s.nagadNumber?` · ${esc(s.nagadNumber)}`:''}</label>`).join('')}</div><button class="btn" type="submit">PLACE ORDER — ${money(getTotals().total)} →</button></form><div id="checkout-side"><div id="checkout-summary">${summary()}</div><div class="coupon-box"><label for="coupon-input">Coupon code</label><div><input id="coupon-input" value="${esc(read('sazCouponCode',''))}" placeholder="Enter coupon code"><button type="button" class="btn small" data-action="apply-coupon">Apply</button></div><p id="coupon-message"></p></div><div class="form-card" style="margin-top:14px">${cart.map(x=>`<p class="summary-row"><span>${esc(product(x.id).name)} × ${x.qty}</span><b>${money(product(x.id).price*x.qty)}</b></p>`).join('')}</div></div></div></main>`;}
  const fallbackSlideArt='data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 700"><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#17150f"/><stop offset=".52" stop-color="#080807"/><stop offset="1" stop-color="#211b0d"/></linearGradient><linearGradient id="cloth" x2=".8" y2="1"><stop stop-color="#f2eee4"/><stop offset="1" stop-color="#b9b2a2"/></linearGradient><radialGradient id="glow"><stop stop-color="#d4af37" stop-opacity=".2"/><stop offset="1" stop-color="#d4af37" stop-opacity="0"/></radialGradient></defs><rect width="1600" height="700" fill="url(#bg)"/><ellipse cx="1120" cy="360" rx="390" ry="390" fill="url(#glow)"/><path d="M1000 165c-11-82 52-128 139-128s150 46 139 128l169 106-77 138-94-57v264H1000V352l-94 57-77-138z" fill="url(#cloth)" stroke="#d4af37" stroke-width="5" stroke-linejoin="round"/><path d="M1054 170c18 50 52 76 85 76s67-26 85-76M1000 352v264m278-264v264M1080 442h118l25 93h-168z" fill="none" stroke="#a98b37" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/><path d="M1139 249v367" stroke="#8b835f" stroke-width="4"/><circle cx="1139" cy="316" r="5" fill="#b18f37"/><circle cx="1139" cy="360" r="5" fill="#b18f37"/><circle cx="1139" cy="404" r="5" fill="#b18f37"/></svg>');
  function getCarouselSlides(){let c=getSiteContent(),fallback=products.find(p=>p.active!==false&&(p.images?.length||p.image)),fallbackImage=fallback?(fallback.images?.[0]||fallback.image):'';let slides=Array.isArray(c.carouselSlides)&&c.carouselSlides.length?c.carouselSlides:[{image:fallbackImage,title:'',text:'',button:'',link:fallback?`product.html?id=${encodeURIComponent(fallback.id)}`:'shop.html'}];return slides.map(s=>({...s,image:s.image||fallbackImage}));}
  function formattedDescription(value){let blocks=esc(value||'Premium SAZ House streetwear, designed for everyday wear.').split(/\r?\n\s*\r?\n/);return blocks.map(block=>{let lines=block.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(lines.length&&lines.every(x=>x.startsWith('- ')))return `<ul>${lines.map(x=>`<li>${x.slice(2)}</li>`).join('')}</ul>`;return `<p>${lines.join('<br>')}</p>`;}).join('');}
  function paintCarousel(){let slides=[...document.querySelectorAll('.carousel-slide')];if(!slides.length)return;carouselIndex=(carouselIndex+slides.length)%slides.length;slides.forEach((s,i)=>{s.hidden=i!==carouselIndex;s.classList.toggle('active',i===carouselIndex);});document.querySelectorAll('.carousel-dot').forEach((d,i)=>d.classList.toggle('active',i===carouselIndex));}
  function home(){let slides=getCarouselSlides();carouselIndex=Math.min(carouselIndex,slides.length-1);return `<main class="wrap"><section class="home-carousel" aria-label="Featured promotions">${slides.map((s,i)=>`<article class="carousel-slide ${i===carouselIndex?'active':''}" style="--slide-bg:${s.image?.includes('british-style-shirt')?'#eeeae3':s.image?.includes('premium-gift-box')?'#ece5db':s.image?.includes('mally-signature-hoodie')?'#11120f':'#32312c'}" ${i===carouselIndex?'':'hidden'}><a class="carousel-image-link" href="${esc(s.link||'shop.html')}" aria-label="View featured item"><img class="carousel-image" src="${esc(s.image||fallbackSlideArt)}" alt="Featured SAZ House fashion"></a></article>`).join('')}<button class="carousel-control prev" data-action="carousel-prev" aria-label="Previous slide">‹</button><button class="carousel-control next" data-action="carousel-next" aria-label="Next slide">›</button><div class="carousel-dots">${slides.map((_,i)=>`<button class="carousel-dot ${i===carouselIndex?'active':''}" data-action="carousel-go" data-index="${i}" aria-label="Go to slide ${i+1}"></button>`).join('')}</div></section><div class="benefits"><div class="benefit"><i>♧</i><div><b>Fast & reliable shipping</b><small>Across Bangladesh</small></div></div><div class="benefit"><i>♢</i><div><b>Secure payment</b><small>Safe checkout options</small></div></div><div class="benefit"><i>↻</i><div><b>Easy returns</b><small>7-day return policy</small></div></div><div class="benefit"><i>☏</i><div><b>Customer support</b><small>We're here to help</small></div></div></div><section class="section"><div class="section-head"><div><span class="eyebrow">Shop by category</span><h2>Find Your Style</h2></div><a class="textlink" href="shop.html">View all →</a></div><div class="category-grid">${[['T-Shirts','👕'],['Hoodies','🧥'],['Caps','🧢'],['Jackets','🥼'],['Pants','👖'],['Accessories','🎒']].map(([n,i])=>`<a class="category" href="shop.html?category=${encodeURIComponent(n)}"><span>${i}</span><b>${n}</b></a>`).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">Featured products</span><h2>Best Sellers</h2></div><a class="textlink" href="shop.html">View all →</a></div><div class="grid">${productsForPage('homeFeatured').map(card).join('')}</div></section></main>`;}
  function productPage(){selected=new URLSearchParams(location.search).get('id')||'hoodie';let p=product(selected),sizes=p.sizes||['S','M','L','XL','XXL'],colors=(p.colors?.length?p.colors:[p.color||'Black']);chosenSize=sizes.includes(chosenSize)?chosenSize:(sizes.includes('M')?'M':sizes[0]);chosenColor=colors.includes(chosenColor)?chosenColor:colors[0];return `<main class="wrap page"><div class="breadcrumbs"><a href="index.html">Home</a>　›　<a href="shop.html">Shop</a>　›　${esc(p.category)}　›　${esc(p.name)}</div><div class="product-detail"><div class="detail-art">${art(p)}${p.video?`<video class="product-video" controls preload="metadata" src="${esc(p.video)}"></video>`:''}</div><div class="detail-info"><span class="eyebrow">${esc(p.category)} · SAZ Originals</span><h1>${esc(p.name)}</h1><span class="rating">★★★★★</span><p class="price" style="margin:16px 0">${money(p.price)} ${p.old?`<span class="old">${money(p.old)}</span>`:''}</p><p class="muted">${esc(p.descriptionSummary||'')}</p><p><b>Color:</b> <span id="selected-color">${esc(chosenColor)}</span></p><div class="product-color-options">${colors.map(c=>`<button type="button" class="color-choice ${c===chosenColor?'selected':''}" data-action="color" data-color="${esc(c)}">${esc(c)}</button>`).join('')}</div><p><b>Size:</b> <span id="selected-size">${esc(chosenSize)}</span></p><div class="sizes">${sizes.map(s=>`<button class="size ${s===chosenSize?'selected':''}" data-action="size" data-size="${esc(s)}">${esc(s)}</button>`).join('')}</div><div class="qty"><span>Quantity</span><button data-action="qty-minus">−</button><b id="qty-val">1</b><button data-action="qty-plus">＋</button></div><button class="btn" data-action="add-detail" data-id="${esc(p.id)}">ADD TO CART — ${money(p.price)}</button><button class="btn secondary" data-action="buy" data-id="${esc(p.id)}">BUY NOW</button><p class="muted">✓ Premium quality &nbsp; ✓ Easy returns &nbsp; ✓ Secure checkout</p></div></div><section class="product-description"><h2>Product details</h2><div class="formatted-description">${formattedDescription(p.description)}</div></section><section class="product-description"><h2>Shipping & Returns</h2><p>Delivery takes 1–3 business days in Dhaka and 3–5 days elsewhere. Unused products can be returned within 7 days.</p></section><section class="section"><div class="section-head"><h2>You may also like</h2></div><div class="grid">${products.filter(x=>x.id!==p.id&&x.active!==false).slice(0,4).map(card).join('')}</div></section></main>`;}
  function cartPage(){let t=getTotals();return `<main class="wrap page"><div class="breadcrumbs"><a href="index.html">Home</a>　›　Cart</div><h1 class="page-title">Your Cart (${count()})</h1><p class="muted">Review your items before checkout.</p><div class="cart-layout" style="margin-top:22px"><div>${cart.length?cart.map((x,index)=>{let p=product(x.id);return `<div class="cart-item">${art(p)}<div class="cart-item-main"><h3><a href="product.html?id=${encodeURIComponent(p.id)}">${esc(p.name)}</a></h3><p>Color: ${esc(x.color||p.color)} · Size ${esc(x.size||'M')}</p><b>${money(p.price)}</b><div class="cart-qty"><button data-action="cart-minus" data-index="${index}">−</button><span>${x.qty}</span><button data-action="cart-plus" data-index="${index}">＋</button></div></div><button class="remove" data-action="remove" data-index="${index}" aria-label="Remove">×</button></div>`}).join(''):`<div class="empty"><h2>Your cart is empty</h2><a class="btn" href="shop.html">CONTINUE SHOPPING →</a></div>`}</div>${cart.length?`<div>${summary()}<a href="checkout.html" class="btn" style="width:100%;margin-top:13px">PROCEED TO CHECKOUT →</a><p style="text-align:center"><a href="shop.html" class="textlink">Continue shopping</a></p></div>`:''}</div></main>`;}
  document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='color'){e.preventDefault();e.stopImmediatePropagation();chosenColor=b.dataset.color;galleryIndex=0;document.getElementById('selected-color').textContent=chosenColor;document.querySelectorAll('.color-choice').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});let detailArt=document.querySelector('.detail-art'),p=product(selected);if(detailArt){let video=detailArt.querySelector('video')?.outerHTML||'';detailArt.innerHTML=art(p)+video;}return;}if(a==='carousel-prev'||a==='carousel-next'||a==='carousel-go'){e.preventDefault();e.stopImmediatePropagation();let n=document.querySelectorAll('.carousel-slide').length;if(!n)return;carouselIndex=a==='carousel-go'?Number(b.dataset.index):(carouselIndex+(a==='carousel-next'?1:n-1))%n;paintCarousel();return;}if(['cart-plus','cart-minus','remove'].includes(a)&&b.dataset.index!==undefined){e.preventDefault();e.stopImmediatePropagation();let i=Number(b.dataset.index),row=cart[i];if(!row)return;if(a==='remove')cart.splice(i,1);else{let p=product(row.id);if(a==='cart-plus'&&Number.isFinite(Number(p.stock))&&row.qty>=Number(p.stock)){toast('Only '+p.stock+' in stock');return;}row.qty+=a==='cart-plus'?1:-1;if(row.qty<1)cart.splice(i,1);}persistCart();renderCart();}},true);
  const closeNavMenus=keep=>document.querySelectorAll('.nav-item[open]').forEach(item=>{if(item!==keep)item.open=false;});
