  const syncSlideProductChoices=()=>document.querySelectorAll('#home-slideshow-form .home-slide-editor').forEach(row=>{let link=row.querySelector('[name="link"]')?.value.trim(),select=row.querySelector('[data-slide-product]');if(select)select.value=[...select.options].some(o=>o.value===link)?link:'';});
  const slideshowObserver=new MutationObserver(syncSlideProductChoices);slideshowObserver.observe(app,{childList:true,subtree:true});
