  function add(id,qty=1,size=null,color=null){let p=product(id);size=size||(p.sizes?.includes('M')?'M':p.sizes?.[0]||'One Size');color=color||(p.colors?.[0]||p.color||'Black');if(Number.isFinite(Number(p.stock))&&Number(p.stock)<=0){toast('This product is currently out of stock');return false;}let row=cart.find(x=>x.id===id&&x.size===size&&(x.color||p.color)===color),next=(row?.qty||0)+qty;if(Number.isFinite(Number(p.stock))&&next>Number(p.stock)){toast(`Only ${p.stock} in stock`);return false;}if(row)row.qty=next;else cart.push({id,qty,size,color});persistCart();toast(`${p.name} added to your cart`);return true;}
