  document.addEventListener('change',e=>{if(page==='shop'&&(e.target.matches('input[name=category]')||e.target.matches('.size-filter')||e.target.matches('.color-filter')||e.target.id==='sort'||e.target.id==='price-range'))applyFilters();if(page==='admin'&&e.target.matches('[data-action="order-status"]')){let orders=read('sazOrders',[]);if(orders[e.target.dataset.index]){orders[e.target.dataset.index].status=e.target.value;save('sazOrders',orders);toast('Order status updated');}}});
