  document.addEventListener('change',e=>{if(e.target.id==='admin-backup-file'&&e.target.files?.[0]){let reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result);if(!Array.isArray(data.products)||!Array.isArray(data.orders)||!Array.isArray(data.coupons))throw new Error('Invalid backup');if(!confirm('Restore this backup? It will replace this browser’s current products, product types, orders, coupons, site content and settings.'))return;products=data.products;save('sazProducts',products);save('sazOrders',data.orders);save('sazCoupons',data.coupons);if(Array.isArray(data.productTypes)){productTypes=data.productTypes;save('sazProductTypes',productTypes);}if(data.settings)save('sazSettings',data.settings);if(data.siteContent)save('sazSiteContent',data.siteContent);if(data.pageProducts)save('sazPageProducts',data.pageProducts);if(Array.isArray(data.homeCategories))save('sazHomeCategories',data.homeCategories);if(Array.isArray(data.messages))save('sazMessages',data.messages);location.reload();}catch(err){toast('Could not restore this backup file');}};reader.readAsText(e.target.files[0]);}});
